import sys

def main():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    q = int(input_data[0])

    history = []

    current_assignments = {}

    idx = 1
    for day in range(1, q + 1):
        line = input_data[idx].strip()
        idx += 1
        parts = line.split()
        op_type = parts[0]

        if op_type == 'set':
            name = parts[1]
            priority = int(parts[2])

            old_state = None
            if name in current_assignments:
                old_state = (name, current_assignments[name])

            current_assignments[name] = priority

            history.append({
                'type': 'set',
                'name': name,
                'old_value': old_state
            })

        elif op_type == 'remove':
            name = parts[1]

            old_state = None
            if name in current_assignments and current_assignments[name] is not None:
                old_state = (name, current_assignments[name])
                del current_assignments[name]
            else:
                pass 

            history.append({
                'type': 'remove',
                'name': name,
                'old_value': old_value if (old_state := (name, current_assignments.get(name))) else None
            })

            # Correct logic for remove:
            # We need to record what was there before removal to restore it.
            # If it wasn't there, we record None.
            if name in current_assignments:
                val = current_assignments[name]
                del current_assignments[name]
                history[-1]['old_value'] = (name, val)
            else:
                history[-1]['old_value'] = None

        elif op_type == 'query':
            name = parts[1]

            if name not in current_assignments:
                print(-1)
            else:
                target_priority = current_assignments[name]
                count = 0
                for other_name, other_priority in current_assignments.items():
                    if other_priority < target_priority:
                        count += 1
                print(count)

            history.append({
                'type': 'query',
                'name': name
            })

        elif op_type == 'undo':
            d = int(parts[1])

            # Undo d operations
            # The operations to undo are the last d operations in history
            # We need to pop them and revert their effects

            ops_to_undo = []
            while d > 0 and len(history) > 0:
                ops_to_undo.append(history.pop())
                d -= 1

            # Revert in reverse order of popping (which is reverse chronological)
            # But since we popped from the end, the last popped is the most recent.
            # To revert correctly, we must apply the inverse in reverse order of execution.
            # So we iterate ops_to_undo in reverse.

            for action in reversed(ops_to_undo):
                atype = action['type']
                name = action['name']

                if atype == 'set':
                    old_val = action['old_value']
                    if old_val is None:
                        # It was a new addition, so remove it
                        if name in current_assignments:
                            del current_assignments[name]
                    else:
                        # Restore old value
                        current_assignments[name] = old_val[1]

                elif atype == 'remove':
                    old_val = action['old_value']
                    if old_value is not None:
                        # Restore the removed item
                        current_assignments[name] = old_val[1]
                    # If it was not there, nothing to do

                elif atype == 'query':
                    # Query has no side effect, just ignore
                    pass

